import { clamp01, clamp11, clampNyquist } from '../util'
import { Gen } from './gen'

export class Osc extends Gen {
  hz$: usize = 0
  ceil$: usize = 0
  width$: usize = 0
  offset$: usize = 0
  trig$: usize = 0

  phase: f32 = 0.0
  lastTrig: f32 = 0.0
  lastOutput: f32 = 0.0

  reset(): void {
    this.phase = 0.0
    this.lastTrig = 0.0
    this.lastOutput = 0.0
  }

  copyFrom(other: Gen): void {
    const src = other as Osc
    this.phase = src.phase
    this.lastTrig = src.lastTrig
    this.lastOutput = src.lastOutput
  }

  process(out$: usize, length: i32): void {}

  @inline
  private polyBlep(phase: f32, phaseInc: f32): f32 {
    if (phaseInc <= 0.0) return 0.0

    if (phase < phaseInc) {
      const t: f32 = phase / phaseInc
      return t + t - t * t - 1.0
    }

    if (phase > 1.0 - phaseInc) {
      const t: f32 = (phase - 1.0) / phaseInc
      return t * t + t + t + 1.0
    }

    return 0.0
  }

  @inline
  sin(out$: usize, length: i32): void {
    let hz$ = this.hz$
    let offset$ = this.offset$
    let trig$ = this.trig$

    let phase: f32 = this.phase
    let lastTrig: f32 = this.lastTrig
    let lastOutput: f32 = this.lastOutput

    for (let i = 0; i < length; i++) {
      const hz: f32 = clampNyquist(load<f32>(hz$))
      const trig: f32 = load<f32>(trig$)

      if (trig > 0.0 && lastTrig <= 0.0) {
        const offsetSeconds: f32 = load<f32>(offset$)
        let phaseOffset: f32 = (offsetSeconds * hz) % 1.0
        if (phaseOffset < 0.0) phaseOffset += 1.0
        phase = phaseOffset
        lastOutput = 0.0
      }
      lastTrig = trig

      store<f32>(out$, Mathf.sin(phase * TWO_PI))

      phase += hz / sampleRate
      if (phase >= 1.0) phase -= 1.0

      out$ += 4
      hz$ += 4
      trig$ += 4
      offset$ += 4
    }

    this.phase = phase
    this.lastTrig = lastTrig
    this.lastOutput = lastOutput
  }

  @inline
  tri(out$: usize, length: i32): void {
    let hz$ = this.hz$
    let offset$ = this.offset$
    let trig$ = this.trig$

    let phase: f32 = this.phase
    let lastTrig: f32 = this.lastTrig
    let lastOutput: f32 = this.lastOutput

    for (let i = 0, hz: f32, trig: f32, offsetSeconds: f32, phaseOffset: f32, phaseInc: f32, saw: f32, integrated: f32,
      out: f32; i < length; i += 16)
    {
      unroll(16, () => {
        hz = clampNyquist(load<f32>(hz$))
        trig = load<f32>(trig$)

        if (trig > 0.0 && lastTrig <= 0.0) {
          offsetSeconds = load<f32>(offset$)
          phaseOffset = (offsetSeconds * hz) % 1.0
          if (phaseOffset < 0.0) phaseOffset += 1.0
          phase = phaseOffset
          lastOutput = 0.0
        }
        lastTrig = trig

        phaseInc = hz / sampleRate

        saw = 2.0 * phase - 1.0
        saw -= this.polyBlep(phase, phaseInc)

        integrated = phaseInc * saw + (1.0 - phaseInc) * lastOutput
        out = integrated * 6.0
        lastOutput = integrated

        store<f32>(out$, out)

        phase += phaseInc
        if (phase >= 1.0) phase -= 1.0

        out$ += 4
        hz$ += 4
        trig$ += 4
        offset$ += 4
      })
    }

    this.phase = phase
    this.lastTrig = lastTrig
    this.lastOutput = lastOutput
  }

  @inline
  saw(out$: usize, length: i32): void {
    let hz$ = this.hz$
    let offset$ = this.offset$
    let trig$ = this.trig$

    let phase: f32 = this.phase
    let lastTrig: f32 = this.lastTrig
    let lastOutput: f32 = this.lastOutput

    for (let i = 0, hz: f32, trig: f32, offsetSeconds: f32, phaseOffset: f32, phaseInc: f32, value: f32; i < length;
      i += 16)
    {
      unroll(16, () => {
        hz = clampNyquist(load<f32>(hz$))
        trig = load<f32>(trig$)

        if (trig > 0.0 && lastTrig <= 0.0) {
          offsetSeconds = load<f32>(offset$)
          phaseOffset = (offsetSeconds * hz) % 1.0
          if (phaseOffset < 0.0) phaseOffset += 1.0
          phase = phaseOffset
          lastOutput = 0.0
        }
        lastTrig = trig

        phaseInc = hz / sampleRate

        value = 2.0 * phase - 1.0
        value -= this.polyBlep(phase, phaseInc)
        store<f32>(out$, value)

        phase += phaseInc
        if (phase >= 1.0) phase -= 1.0

        out$ += 4
        hz$ += 4
        trig$ += 4
        offset$ += 4
      })
    }

    this.phase = phase
    this.lastTrig = lastTrig
    this.lastOutput = lastOutput
  }

  @inline
  ramp(out$: usize, length: i32): void {
    this.saw(out$, length)

    let p$ = out$
    for (let i = 0; i < length; i += 16) {
      unroll(16, () => {
        store<f32>(p$, -load<f32>(p$))
        p$ += 4
      })
    }
  }

  @inline
  sqr(out$: usize, length: i32): void {
    let hz$ = this.hz$
    let offset$ = this.offset$
    let trig$ = this.trig$

    let phase: f32 = this.phase
    let lastTrig: f32 = this.lastTrig
    let lastOutput: f32 = this.lastOutput

    for (let i = 0, hz: f32, trig: f32, offsetSeconds: f32, phaseOffset: f32, phaseInc: f32, value: f32; i < length;
      i += 16)
    {
      unroll(16, () => {
        hz = clampNyquist(load<f32>(hz$))
        trig = load<f32>(trig$)

        if (trig > 0.0 && lastTrig <= 0.0) {
          offsetSeconds = load<f32>(offset$)
          phaseOffset = (offsetSeconds * hz) % 1.0
          if (phaseOffset < 0.0) phaseOffset += 1.0
          phase = phaseOffset
          lastOutput = 0.0
        }
        lastTrig = trig

        phaseInc = hz / sampleRate

        value = phase < 0.5 ? 1.0 : -1.0
        value += this.polyBlep(phase, phaseInc)
        value -= this.polyBlep((phase + 0.5) % 1.0, phaseInc)
        store<f32>(out$, value)

        phase += phaseInc
        if (phase >= 1.0) phase -= 1.0

        out$ += 4
        hz$ += 4
        trig$ += 4
        offset$ += 4
      })
    }

    this.phase = phase
    this.lastTrig = lastTrig
    this.lastOutput = lastOutput
  }

  @inline
  pwm(out$: usize, length: i32): void {
    let hz$ = this.hz$
    let width$ = this.width$
    let offset$ = this.offset$
    let trig$ = this.trig$

    let phase: f32 = this.phase
    let lastTrig: f32 = this.lastTrig
    let lastOutput: f32 = this.lastOutput

    for (let i = 0; i < length; i++) {
      const hz: f32 = clampNyquist(load<f32>(hz$))
      const trig: f32 = load<f32>(trig$)
      if (trig > 0.0 && lastTrig <= 0.0) {
        const offsetSeconds: f32 = load<f32>(offset$)
        let phaseOffset: f32 = (offsetSeconds * hz) % 1.0
        if (phaseOffset < 0.0) phaseOffset += 1.0
        phase = phaseOffset
        lastOutput = 0.0
      }
      lastTrig = trig

      const phaseInc: f32 = hz / sampleRate
      const pulseWidth: f32 = clamp01(load<f32>(width$)) * .985 + .0075

      let value: f32 = phase < pulseWidth ? 1.0 : -1.0

      value += this.polyBlep(phase, phaseInc)

      let fallingPhase: f32 = phase - pulseWidth
      if (fallingPhase < 0.0) fallingPhase += 1.0
      value -= this.polyBlep(fallingPhase, phaseInc)

      store<f32>(out$, value)

      phase += phaseInc
      if (phase >= 1.0) phase -= 1.0

      out$ += 4
      hz$ += 4
      width$ += 4
      offset$ += 4
      trig$ += 4
    }

    this.phase = phase
    this.lastTrig = lastTrig
    this.lastOutput = lastOutput
  }

  @inline
  impulse(out$: usize, length: i32): void {
    let hz$ = this.hz$
    let offset$ = this.offset$
    let trig$ = this.trig$

    let phase: f32 = this.phase
    let lastTrig: f32 = this.lastTrig

    for (let i = 0; i < length; i++) {
      const hz: f32 = clampNyquist(load<f32>(hz$))
      const trig: f32 = load<f32>(trig$)

      if (trig > 0.0 && lastTrig <= 0.0) {
        const offsetSeconds: f32 = load<f32>(offset$)
        let phaseOffset: f32 = (offsetSeconds * hz) % 1.0
        if (phaseOffset < 0.0) phaseOffset += 1.0
        phase = phaseOffset
      }
      lastTrig = trig

      const phaseInc: f32 = hz / sampleRate

      if (phase === 0 || phase >= 1.0) {
        if (phase > 1.0) phase -= 1.0
        store<f32>(out$, 1.0)
      }
      else {
        store<f32>(out$, 0.0)
      }
      phase += phaseInc

      out$ += 4
      hz$ += 4
      trig$ += 4
      offset$ += 4
    }

    this.phase = phase
    this.lastTrig = lastTrig
  }

  @inline
  inc(out$: usize, length: i32): void {
    let hz$ = this.hz$
    let ceil$ = this.ceil$
    let offset$ = this.offset$
    let trig$ = this.trig$

    let phase: f32 = this.phase
    let lastTrig: f32 = this.lastTrig

    for (let i = 0; i < length; i++) {
      const hz: f32 = clampNyquist(load<f32>(hz$))
      const ceil: f32 = load<f32>(ceil$)
      const trig: f32 = load<f32>(trig$)

      if (trig > 0.0 && lastTrig <= 0.0) {
        const offsetSeconds: f32 = load<f32>(offset$)
        phase = offsetSeconds
      }
      lastTrig = trig

      store<f32>(out$, phase)

      phase += hz / sampleRate
      if (phase > ceil) {
        phase = ceil
      }

      out$ += 4
      hz$ += 4
      ceil$ += 4
      trig$ += 4
      offset$ += 4
    }

    this.phase = phase
    this.lastTrig = lastTrig
  }

  @inline
  phasor(out$: usize, length: i32): void {
    let hz$ = this.hz$
    let offset$ = this.offset$
    let trig$ = this.trig$

    let phase: f32 = this.phase
    let lastTrig: f32 = this.lastTrig

    for (let i = 0; i < length; i++) {
      const hz: f32 = clampNyquist(load<f32>(hz$))
      const trig: f32 = load<f32>(trig$)

      if (trig > 0.0 && lastTrig <= 0.0) {
        const offsetSeconds: f32 = load<f32>(offset$)
        let phaseOffset: f32 = (offsetSeconds * hz) % 1.0
        if (phaseOffset < 0.0) phaseOffset += 1.0
        phase = phaseOffset
      }
      lastTrig = trig

      store<f32>(out$, phase)
      phase += hz / sampleRate
      if (phase >= 1.0) {
        phase = 0.0
      }

      out$ += 4
      hz$ += 4
      trig$ += 4
      offset$ += 4
    }

    this.phase = phase
    this.lastTrig = lastTrig
  }
}

export class Tri extends Osc {
  process(out$: usize, length: i32): void {
    this.tri(out$, length)
  }
}

export class Saw extends Osc {
  process(out$: usize, length: i32): void {
    this.saw(out$, length)
  }
}

export class Ramp extends Osc {
  process(out$: usize, length: i32): void {
    this.ramp(out$, length)
  }
}

export class Sqr extends Osc {
  process(out$: usize, length: i32): void {
    this.sqr(out$, length)
  }
}

export class Pwm extends Osc {
  process(out$: usize, length: i32): void {
    this.pwm(out$, length)
  }
}

export class Phasor extends Osc {
  process(out$: usize, length: i32): void {
    this.phasor(out$, length)
  }
}

export class Impulse extends Osc {
  process(out$: usize, length: i32): void {
    this.impulse(out$, length)
  }
}

export class Inc extends Osc {
  process(out$: usize, length: i32): void {
    this.inc(out$, length)
  }
}
