import { applyCurve } from '../util'
import { Gen } from './gen'

enum Phase {
  Idle,
  Attack,
  Decay,
}

export class Ad extends Gen {
  attack$: usize = 0
  decay$: usize = 0
  exponent$: usize = 0
  trig$: usize = 0

  private phase: Phase = Phase.Idle
  private position: f32 = 0
  private lastTrig: f32 = 0

  // Best-effort UI/debug state (read by UI history writers).
  visPhase: i32 = Phase.Idle
  visPhase01: f32 = 0.0

  reset(): void {
    this.phase = Phase.Idle
    this.position = 0
    this.lastTrig = 0
    this.visPhase = Phase.Idle
    this.visPhase01 = 0.0
  }

  copyFrom(other: Gen): void {
    const src = other as Ad
    this.phase = src.phase
    this.position = src.position
    this.lastTrig = src.lastTrig
    this.visPhase = src.visPhase
    this.visPhase01 = src.visPhase01
  }

  @inline
  generate(attack: f32, decay: f32, exponent: f32, trig: f32): f32 {
    const isTrigger = trig > 0 && this.lastTrig <= 0
    this.lastTrig = trig

    if (isTrigger) {
      this.phase = Phase.Attack
      this.position = 0
    }

    if (this.phase === Phase.Idle) {
      this.visPhase = Phase.Idle
      this.visPhase01 = 0.0
      return 0
    }

    if (this.phase === Phase.Attack) {
      const attackSamples = attack * sampleRate
      if (attackSamples <= 0) {
        this.position = 1
        this.phase = Phase.Decay
      }
      else {
        this.position += 1.0 / attackSamples
        if (this.position >= 1.0) {
          this.position = 1.0
          this.phase = Phase.Decay
        }
      }
      this.visPhase = Phase.Attack
      this.visPhase01 = Mathf.max(0.0, Mathf.min(this.position, 1.0))
      return f32(applyCurve(this.position, exponent))
    }

    if (this.phase === Phase.Decay) {
      const decaySamples = decay * sampleRate
      if (decaySamples <= 0) {
        this.position = 0
        this.phase = Phase.Idle
      }
      else {
        const delta: f32 = 1.0 / decaySamples
        this.position -= delta
        if (this.position <= 0) {
          this.position = 0
          this.phase = Phase.Idle
        }
      }
      this.visPhase = this.phase === Phase.Idle ? Phase.Idle : Phase.Decay
      const t: f32 = 1.0 - this.position
      this.visPhase01 = Mathf.max(0.0, Mathf.min(t, 1.0))
      return f32(applyCurve(this.position, exponent))
    }

    return 0
  }

  process(out$: usize, length: i32): void {
    let attack$ = this.attack$
    let decay$ = this.decay$
    let exponent$ = this.exponent$
    let trig$ = this.trig$

    for (let i: i32 = 0, sample: f32; i < length; i += 16) {
      unroll(16, () => {
        sample = this.generate(
          load<f32>(attack$),
          load<f32>(decay$),
          load<f32>(exponent$),
          load<f32>(trig$),
        )

        store<f32>(out$, sample)

        out$ += 4
        attack$ += 4
        decay$ += 4
        exponent$ += 4
        trig$ += 4
      })
    }
  }
}
